    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start < 0 || end < 0 || end <= start) return null;
    const jsonStr = cleaned.slice(start, end + 1);
    const parsed = JSON.parse(jsonStr) as {
      rootCause?: string;
      technicalPlan?: string;
      operations?: Array<{
        path?: string;
        kind?: string;
        oldText?: string;
        newText?: string;
        reason?: string;
      }>;
    };
